#!/usr/bin/env python3
# Створено штучним інтелектом (Claude, Anthropic) на замовлення lokinyauv-create. / Generated by AI (Claude).
"""Вікно оновлювача Proton."""
import sys, threading
from PySide6.QtCore import QObject, Qt, Signal
from PySide6.QtWidgets import (QApplication, QComboBox, QDialog, QDialogButtonBox, QHBoxLayout, QLabel,
                               QMessageBox, QPushButton, QTableWidget, QTableWidgetItem, QVBoxLayout, QWidget,
                               QAbstractItemView, QHeaderView, QListWidget, QPlainTextEdit)
import protonupd as P


class Bg(QObject):
    done = Signal(object, object)   # результат, помилка
    line = Signal(str)

    def run(self, fn):
        def w():
            try:
                self.done.emit(fn(self.line.emit), None)
            except Exception as e:
                self.done.emit(None, e)
        threading.Thread(target=w, daemon=True).start()


class Main(QWidget):
    def __init__(self):
        super().__init__()
        self.setWindowTitle("Оновлювач Proton")
        self.resize(900, 460)
        self.c = P.load()
        self.latest = {}
        v = QVBoxLayout(self)
        self.table = QTableWidget(0, 5)
        self.table.setHorizontalHeaderLabels(["Гра", "Джерело", "Зараз у Steam", "Остання", "Версія"])
        self.table.setSelectionBehavior(QAbstractItemView.SelectRows)
        self.table.setSelectionMode(QAbstractItemView.SingleSelection)
        self.table.setEditTriggers(QAbstractItemView.NoEditTriggers)
        self.table.horizontalHeader().setSectionResizeMode(QHeaderView.Stretch)
        v.addWidget(self.table)
        self.info = QLabel()
        self.info.setWordWrap(True)
        v.addWidget(self.info)
        row = QHBoxLayout()
        for text, fn in [("Додати гру", self.add_game), ("Прибрати гру", self.remove_game),
                         ("Вибрати версію…", self.pick_version), ("Завжди остання", self.unpin),
                         ("Перевірити й оновити", self.check_now),
                         ("Перезапустити Steam", self.restart_steam),
                         ("Звідки це?", self.about)]:
            b = QPushButton(text); b.clicked.connect(fn); row.addWidget(b)
        v.addLayout(row)
        self.log = QPlainTextEdit(); self.log.setReadOnly(True); self.log.setMaximumHeight(110)
        v.addWidget(self.log)
        self.bg = Bg(); self.bg.line.connect(self.log.appendPlainText)
        self.refresh()
        self.bg.run(self._fetch_latest); self.bg.done.connect(self._fetched)

    def _fetch_latest(self, log):
        return {s: P.releases(s)[:1] for s in P.SOURCES}

    def _fetched(self, res, err):
        if res and not hasattr(self, "_got"):
            self._got = True
            self.latest = {s: (r[0]["name"] if r else "?") for s, r in res.items()}
            self.refresh()

    def refresh(self):
        self.table.setRowCount(0)
        for appid, g in self.c["games"].items():
            r = self.table.rowCount(); self.table.insertRow(r)
            cur = P.current_tool(appid) or "—"
            if appid in self.c["pending"]:
                cur += f"  (чекає закриття Steam → {self.c['pending'][appid]})"
            vals = [f"{g['name']}", P.SOURCES[g["source"]]["title"], cur,
                    self.latest.get(g["source"], "…"), g.get("pin") or "завжди остання"]
            for i, t in enumerate(vals):
                it = QTableWidgetItem(t); it.setData(Qt.UserRole, appid); self.table.setItem(r, i, it)
        self.info.setText("Програма сама перевіряє нові версії раз на 12 годин (таймер systemd). "
                          "Перемикає гру в Steam тільки коли Steam закритий.")

    def sel(self):
        r = self.table.currentRow()
        return self.table.item(r, 0).data(Qt.UserRole) if r >= 0 else None

    def save(self):
        P.save(self.c); self.refresh()

    def add_game(self):
        d = QDialog(self); d.setWindowTitle("Додати гру"); l = QVBoxLayout(d)
        lst = QListWidget(); games = {a: n for a, n in P.steam_games().items() if a not in self.c["games"]}
        for a, n in games.items():
            lst.addItem(f"{n}  [{a}]")
        l.addWidget(lst)
        cb = QComboBox()
        for k, s in P.SOURCES.items():
            cb.addItem(s["title"], k)
        l.addWidget(cb)
        bb = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
        bb.accepted.connect(d.accept); bb.rejected.connect(d.reject); l.addWidget(bb)
        if d.exec() and lst.currentRow() >= 0:
            a = list(games)[lst.currentRow()]
            self.c["games"][a] = {"name": games[a], "source": cb.currentData(), "pin": None}
            self.save()

    def remove_game(self):
        a = self.sel()
        if a and QMessageBox.question(self, "Прибрати", "Перестати стежити за цією грою? (Proton у Steam лишиться як є)") \
                == QMessageBox.Yes:
            self.c["games"].pop(a, None); self.c["pending"].pop(a, None); self.save()

    def unpin(self):
        a = self.sel()
        if a:
            self.c["games"][a]["pin"] = None; self.save()

    def pick_version(self):
        a = self.sel()
        if not a:
            return
        src = self.c["games"][a]["source"]
        try:
            rels = P.releases(src, 40)
        except Exception as e:
            QMessageBox.warning(self, "Помилка", str(e)); return
        d = QDialog(self); d.setWindowTitle("Яку версію?"); l = QVBoxLayout(d)
        lst = QListWidget()
        for r in rels:
            lst.addItem(f"{r['name']}   {r['date']}   {r['size'] // 1048576} МБ")
        l.addWidget(lst)
        l.addWidget(QLabel("Версію буде закріплено: автооновлення цієї гри зупиниться, поки не натиснеш «Завжди остання»."))
        bb = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
        bb.accepted.connect(d.accept); bb.rejected.connect(d.reject); l.addWidget(bb)
        if d.exec() and lst.currentRow() >= 0:
            rel = rels[lst.currentRow()]
            self.c["games"][a]["pin"] = rel["name"]
            self.save()
            self.check_now()

    def check_now(self):
        self.log.appendPlainText("Перевіряю…")
        def job(log):
            c = P.load(); c["games"] = self.c["games"]
            P.check(c, log); P.apply_pending(c, log)
            return c
        self.bg.done.disconnect(); self.bg.done.connect(self._checked)
        self.bg.run(job)

    def about(self):
        a = self.sel()
        if not a:
            QMessageBox.information(self, "Звідки це?", "Спершу вибери гру в таблиці."); return
        g = self.c["games"][a]; s = P.SOURCES[g["source"]]
        cur = P.current_tool(a)
        try:
            rels = P.releases(g["source"], 40)
        except Exception as e:
            QMessageBox.warning(self, "Помилка", str(e)); return
        rel = next((r for r in rels if r["name"] == cur), None)
        owner = s["repo"].split("/")[0]
        t = [f"Зараз у Steam: {cur}", "",
             f"Автор: {owner}", f"Репозиторій: https://github.com/{s['repo']}"]
        if rel:
            t += [f"Сторінка цієї версії: {rel['page']}", f"Звідки качається: {rel['url']}",
                  f"Контрольна сума: {rel['sha'] or 'автор не надав'}", f"Дата випуску: {rel['date']}"]
        else:
            t += ["", "Цієї версії немає серед останніх релізів автора на GitHub — "
                  "можливо, вона встановлена не звідти (або дуже стара)."]
        t += ["", "Усе качається тільки з GitHub авторів і перевіряється за sha512."]
        d = QDialog(self); d.setWindowTitle("Звідки це?"); d.resize(760, 300); l = QVBoxLayout(d)
        box = QPlainTextEdit("\n".join(t)); box.setReadOnly(True); l.addWidget(box)
        row = QHBoxLayout()
        b = QPushButton("Відкрити сторінку автора"); b.clicked.connect(
            lambda: __import__("subprocess").Popen(["xdg-open", (rel or {}).get("page") or f"https://github.com/{s['repo']}"]))
        c = QPushButton("Закрити"); c.clicked.connect(d.accept)
        row.addWidget(b); row.addWidget(c); l.addLayout(row)
        d.exec()

    def restart_steam(self):
        if P.game_running():
            QMessageBox.warning(self, "Steam", "Зараз запущена гра — спершу вийди з неї."); return
        if QMessageBox.question(self, "Перезапустити Steam",
                                "Steam закриється й запуститься знову, нова версія Proton застосується. Продовжити?") \
                != QMessageBox.Yes:
            return
        self.log.appendPlainText("Перезапускаю Steam…")
        def job(log):
            c = P.load(); c["games"] = self.c["games"]
            P.check(c, log)
            P.restart_steam(c, log)
            return c
        self.bg.done.disconnect(); self.bg.done.connect(self._checked)
        self.bg.run(job)

    def _checked(self, c, err):
        self.bg.done.disconnect(); self.bg.done.connect(self._fetched)
        if err:
            self.log.appendPlainText(f"Помилка: {err}"); return
        self.c = c
        if c["pending"] and P.steam_running():
            self.log.appendPlainText("Готово. Steam запущений — закрий його, і гра перемкнеться сама (за ≤30 хв).")
        else:
            self.log.appendPlainText("Готово.")
        self.refresh()


if __name__ == "__main__":
    app = QApplication(sys.argv)
    w = Main(); w.show()
    sys.exit(app.exec())
